/*
P3: Synthetischer Vollzeilen- und Metadatenvertrag für drei Showplan-Referenz-TVFs.
51 Fälle verwenden 17 XML-/Statementfiltervarianten und unabhängige Literalorakel.
Der Vertrag prüft 70 vollständige Zeilen einschließlich NULLs und Häufigkeiten,
53 Metadatenfelder und 23 Textcollations. Vollständige Sortties treten nur im
Duplikatfall mit identischen Nutzdaten auf. Die Spaltenrollen werden am jeweiligen
RelOp verwurzelt geprüft; Parent- und Child-NodeIds bleiben getrennt.
Keine echte Blocking-/STATISTICS-/Showplan-Workload und keine Datenbankfixture.
Weitere case-only Sortschlüssel und native ältere Engines sind hier nicht belegt.
*/
SET NOCOUNT ON;
DECLARE @FrameworkLevel int=(SELECT [compatibility_level] FROM sys.databases WHERE [database_id]=DB_ID());
DECLARE @FrameworkCollation sysname=CONVERT(sysname,DATABASEPROPERTYEX(DB_NAME(),N'Collation'));
IF @FrameworkLevel IS NULL OR @FrameworkLevel NOT IN (150,160,170)
    THROW 57300,N'Unexpected framework compatibility level.',1;
IF @FrameworkCollation IS NULL OR @FrameworkCollation<>N'SQL_Latin1_General_CP1_CS_AS'
    THROW 57309,N'Unexpected framework database collation.',1;
DECLARE @Functions TABLE
(
    [FunctionOrdinal] int NOT NULL PRIMARY KEY,
    [FunctionName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL,
    [OrdinalColumn] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
);
