IF EXISTS
(
    SELECT [FunctionOrdinal],[FieldOrdinal],[FieldName],[SystemTypeId],[MaxLength],[PrecisionValue],[ScaleValue],[IsNullable],[CollationName],[IsIdentity] FROM @Metadata
    EXCEPT
    SELECT [f].[FunctionOrdinal],[c].[column_id],[c].[name],[c].[system_type_id],[c].[max_length],[c].[precision],[c].[scale],[c].[is_nullable],[c].[collation_name],[c].[is_identity]
    FROM @Functions AS [f] JOIN sys.columns AS [c] ON [c].[object_id]=OBJECT_ID(N'monitor.'+[f].[FunctionName],N'IF')
)
OR EXISTS
(
    SELECT [f].[FunctionOrdinal],[c].[column_id],[c].[name],[c].[system_type_id],[c].[max_length],[c].[precision],[c].[scale],[c].[is_nullable],[c].[collation_name],[c].[is_identity]
    FROM @Functions AS [f] JOIN sys.columns AS [c] ON [c].[object_id]=OBJECT_ID(N'monitor.'+[f].[FunctionName],N'IF')
    EXCEPT
    SELECT [FunctionOrdinal],[FieldOrdinal],[FieldName],[SystemTypeId],[MaxLength],[PrecisionValue],[ScaleValue],[IsNullable],[CollationName],[IsIdentity] FROM @Metadata

)
