(17,1,N'[{"ReferenceOrdinal":1,"StatementOrdinal":1,"StatementId":6,"StatementCompId":6,"NodeId":1,"ReferenceType":"TABLE","ReferenceSource":"ACCESS_PATH","DatabaseName":"ExampleDbÄ","SchemaName":"ExampleSchema","ObjectName":"ExampleParent","IndexName":null,"AliasName":null,"StorageType":null,"PlanObjectId":null,"PlanIndexId":null,"IsTemporaryObject":0,"IsTableVariable":0,"IsRemoteObject":0,"IsDmlTarget":0,"ResolutionCapability":"CATALOG_RESOLVABLE","SourceElement":"Object"},{"ReferenceOrdinal":2,"StatementOrdinal":1,"StatementId":6,"StatementCompId":6,"NodeId":2,"ReferenceType":"TABLE","ReferenceSource":"ACCESS_PATH","DatabaseName":"ExampleDbÄ","SchemaName":"ExampleSchema","ObjectName":"ExampleChild","IndexName":null,"AliasName":null,"StorageType":null,"PlanObjectId":null,"PlanIndexId":null,"IsTemporaryObject":0,"IsTableVariable":0,"IsRemoteObject":0,"IsDmlTarget":0,"ResolutionCapability":"CATALOG_RESOLVABLE","SourceElement":"Object"}]',2),
(17,2,N'[]',0),
(17,3,N'[{"ColumnReferenceOrdinal":1,"StatementOrdinal":1,"StatementId":6,"StatementCompId":6,"NodeId":1,"ColumnUsage":"OUTPUT","ExpressionContext":"OUTPUT_LIST","DatabaseName":"ExampleDbÄ","SchemaName":"ExampleSchema","ObjectName":"ExampleParent","AliasName":null,"ColumnName":"ExampleParentOutput","IsSeekColumn":false,"IsResidualPredicateColumn":false,"IsJoinColumn":false,"IsGroupByColumn":false,"IsOrderByColumn":false,"IsOutputColumn":true,"IsPartitionColumn":false},{"ColumnReferenceOrdinal":2,"StatementOrdinal":1,"StatementId":6,"StatementCompId":6,"NodeId":1,"ColumnUsage":"SEEK","ExpressionContext":"SEEK_PREDICATE","DatabaseName":"ExampleDbÄ","SchemaName":"ExampleSchema","ObjectName":"ExampleParent","AliasName":null,"ColumnName":"ExampleParentSeek","IsSeekColumn":true,"IsResidualPredicateColumn":false,"IsJoinColumn":false,"IsGroupByColumn":false,"IsOrderByColumn":false,"IsOutputColumn":false,"IsPartitionColumn":false},{"ColumnReferenceOrdinal":3,"StatementOrdinal":1,"StatementId":6,"StatementCompId":6,"NodeId":2,"ColumnUsage":"OUTPUT","ExpressionContext":"OUTPUT_LIST","DatabaseName":"ExampleDbÄ","SchemaName":"ExampleSchema","ObjectName":"ExampleChild","AliasName":null,"ColumnName":"ExampleChildOutput","IsSeekColumn":false,"IsResidualPredicateColumn":false,"IsJoinColumn":false,"IsGroupByColumn":false,"IsOrderByColumn":false,"IsOutputColumn":true,"IsPartitionColumn":false},{"ColumnReferenceOrdinal":4,"StatementOrdinal":1,"StatementId":6,"StatementCompId":6,"NodeId":2,"ColumnUsage":"RESIDUAL","ExpressionContext":"PREDICATE","DatabaseName":"ExampleDbÄ","SchemaName":"ExampleSchema","ObjectName":"ExampleChild","AliasName":null,"ColumnName":"ExampleChildResidual","IsSeekColumn":false,"IsResidualPredicateColumn":true,"IsJoinColumn":false,"IsGroupByColumn":false,"IsOrderByColumn":false,"IsOutputColumn":false,"IsPartitionColumn":false}]',4);
IF (SELECT COUNT(*) FROM @Expected)<>51 OR (SELECT SUM([RowCount]) FROM @Expected)<>70
    THROW 57304,N'Independent literal case matrix is incomplete.',1;
DECLARE @CaseOrdinal int=1,@FunctionOrdinal int,@CaseName nvarchar(128),@Plan xml,@StatementId int,
        @FunctionName sysname,@OrdinalColumn sysname,@ExpectedJson nvarchar(max),@ExpectedCount int,
        @ActualJson nvarchar(max),@NormalizedExpected nvarchar(max),@Projection nvarchar(max),
        @WithColumns nvarchar(max),@Sql nvarchar(max),@PassedCases int=0,@PassedRows int=0;
WHILE @CaseOrdinal<=17
BEGIN
    SELECT @CaseName=[CaseName],@Plan=[PlanXml],@StatementId=[StatementId] FROM @Cases WHERE [CaseOrdinal]=@CaseOrdinal;
    SET @FunctionOrdinal=1;
    WHILE @FunctionOrdinal<=3
    BEGIN
        SELECT @FunctionName=[FunctionName],@OrdinalColumn=[OrdinalColumn] FROM @Functions WHERE [FunctionOrdinal]=@FunctionOrdinal;
        SELECT @ExpectedJson=[RowsJson],@ExpectedCount=[RowCount] FROM @Expected WHERE [CaseOrdinal]=@CaseOrdinal AND [FunctionOrdinal]=@FunctionOrdinal;
        SELECT @Projection=STRING_AGG(CONVERT(nvarchar(max),QUOTENAME([FieldName])),N',') WITHIN GROUP(ORDER BY [FieldOrdinal]),
               @WithColumns=STRING_AGG(CONVERT(nvarchar(max),QUOTENAME([FieldName])+N' '+[SqlType]),N',') WITHIN GROUP(ORDER BY [FieldOrdinal])
        FROM @Metadata WHERE [FunctionOrdinal]=@FunctionOrdinal;
        SET @ActualJson=NULL;
        SET @NormalizedExpected=NULL;
        SET @Sql=N'SELECT @pActual=COALESCE((SELECT * FROM [monitor].'+QUOTENAME(@FunctionName)+N'(@pPlan,@pStatementId) ORDER BY '+QUOTENAME(@OrdinalColumn)+N' FOR JSON PATH,INCLUDE_NULL_VALUES),N''[]'');'
                 +N'SELECT @pNormalized=COALESCE((SELECT '+@Projection+N' FROM OPENJSON(@pExpected) WITH ('+@WithColumns+N') ORDER BY '+QUOTENAME(@OrdinalColumn)+N' FOR JSON PATH,INCLUDE_NULL_VALUES),N''[]'');';
        EXEC sys.sp_executesql @Sql,
             N'@pPlan xml,@pStatementId int,@pExpected nvarchar(max),@pActual nvarchar(max) OUTPUT,@pNormalized nvarchar(max) OUTPUT',
             @pPlan=@Plan,@pStatementId=@StatementId,@pExpected=@ExpectedJson,@pActual=@ActualJson OUTPUT,@pNormalized=@NormalizedExpected OUTPUT;
        IF ISNULL(ISJSON(@ActualJson),0)<>1 OR ISNULL(ISJSON(@NormalizedExpected),0)<>1
           OR LEFT(@ActualJson,1)<>N'[' OR LEFT(@NormalizedExpected,1)<>N'['
            THROW 57305,N'Literal comparison did not produce JSON arrays.',1;
        IF (SELECT COUNT(*) FROM OPENJSON(@ActualJson))<>@ExpectedCount
           OR (SELECT COUNT(*) FROM OPENJSON(@NormalizedExpected))<>@ExpectedCount
        BEGIN
            SELECT @CaseName AS [CaseName],@FunctionName AS [FunctionName],@ExpectedCount AS [ExpectedRowCount],@ActualJson AS [ActualRowsJson];
            THROW 57306,N'Full literal row cardinality differs.',1;
        END;
        IF EXISTS
        (
            SELECT [value] COLLATE Latin1_General_100_BIN2 AS [RowJson],COUNT_BIG(*) AS [Multiplicity]
            FROM OPENJSON(@NormalizedExpected) GROUP BY [value] COLLATE Latin1_General_100_BIN2
            EXCEPT
            SELECT [value] COLLATE Latin1_General_100_BIN2,COUNT_BIG(*)
            FROM OPENJSON(@ActualJson) GROUP BY [value] COLLATE Latin1_General_100_BIN2
        )
        OR EXISTS
        (
            SELECT [value] COLLATE Latin1_General_100_BIN2 AS [RowJson],COUNT_BIG(*) AS [Multiplicity]
            FROM OPENJSON(@ActualJson) GROUP BY [value] COLLATE Latin1_General_100_BIN2
            EXCEPT
            SELECT [value] COLLATE Latin1_General_100_BIN2,COUNT_BIG(*)
            FROM OPENJSON(@NormalizedExpected) GROUP BY [value] COLLATE Latin1_General_100_BIN2
        )
        BEGIN
            SELECT @CaseName AS [CaseName],@FunctionName AS [FunctionName],@NormalizedExpected AS [ExpectedRowsJson],@ActualJson AS [ActualRowsJson];
            THROW 57307,N'Full literal row multiset differs.',1;
        END;
        SET @PassedCases+=1;
        SET @PassedRows+=@ExpectedCount;
        SET @FunctionOrdinal+=1;
    END;
    SET @CaseOrdinal+=1;
END;
IF @PassedCases<>51 OR @PassedRows<>70
    THROW 57308,N'Not all literal cases completed.',1;
SELECT N'PASS' AS [ContractStatus],@FrameworkLevel AS [FrameworkCompatibilityLevel],
       @PassedCases AS [SyntheticCases],@PassedRows AS [LiteralRows],53 AS [MetadataFields],23 AS [TextCollations];
GO
